import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { ProductService } from 'src/app/service/products.service';

@Component({
  selector: 'app-products-edit',
  templateUrl: './products-edit.component.html',
  styleUrls: ['./products-edit.component.css']
})
export class ProductsEditComponent implements OnInit {

  productId:number;
  productFormGroup?:FormGroup;
  submitted:boolean=false;
  //activer l'objet activatedRoute pour recuperer l'id
  constructor (
     private productService:ProductService,
     private fb:FormBuilder, private activatedRoute:ActivatedRoute) {
     this.productId =activatedRoute.snapshot.params['id'];
  }

  ngOnInit():void {
    this.productService.getProduct(this.productId)
      .subscribe(product => {
       this.productFormGroup=this.fb.group({
        id:[product.id,Validators.required],
        name:[product.name,Validators.required],
        price:[product.price,Validators.required],
        quantity:[product.quantity,Validators.required],
        selected:[product.selected,Validators.required],
        available:[product.available,Validators.required],
       })
    });
  }

  onUpdateProduct(){
    this.productService.updateProducts(this.productFormGroup?.value)
      .subscribe(data => {
        alert("Success Product update")
      })
  }
}
<div class="container" *ngIf="productFormGroup">
  <!-- {{productFormGroup.value || json}} -->
<form [formGroup]="productFormGroup">
  <div class="form-group">
    <label>ID</label>
    <input type="text" class="form-control"  formControlName="id">
   </div>
  <!-- <div class="form-group">
    <label>Name</label>
    <input type="text" class="form-control"  formControlName="name"
            [ngClass]="{'is-invalid':submitted && productFormGroup.controls.name.errors}">
            <div *ngIf="submitted && productFormGroup.controls.name.errors" class="invalid-feedback">
               <div *ngIf="productFormGroup.controls.name.errors">Name is required</div>
            </div>
    </div> -->
 <div class="form-group">
  <label>Price</label>
  <input type="text" class="form-control" placeholder="Price" formControlName="price">
 </div>
 <div class="form-group">
  <label>Quantity</label>
  <input type="text" class="form-control" placeholder="Quantity" formControlName="quantity">
</div>

    <div class="form-group">
      <label>Selected</label>
      <input type="checkbox" class="form-check" formControlName="selected">
    </div>
    <div class="form-group">
      <label>Available</label>
      <input type="checkbox" class="form-check" formControlName="available">
    </div>
    <button class="btn btn-success" (click)="onUpdateProduct()">Save</button>
</form>
</div>
